    if self.tpath == '':
        self.tpath = path
    if self.tpath is None:
        if self.tclass == "filesystem":
            self.tpath = ""
        elif self.tclass == "udp_socket" or self.tclass == "tcp_socket":
            self.tpath = _("port %s") % self.port
        else:
            self.tpath = _("Unknown")

