                _set_file_perms(dent_path, inode)
        except Exception as e:
            error(extract_dents, 'Warn', 'FILE Fail: %s' % e)
    elif dent_node.type == UBIFS_ITYPE_LNK:
        try:
            os.symlink('%s' % inode['ino'].data.decode('utf-8'), dent_path)
