    def delete(self, gid):
        """Delete a server group node in the settings database"""
        groups = ServerGroup.query.filter_by(
            user_id=current_user.id
        ).order_by("id")
        sg = groups.first()
        shared_servers = Server.query.filter_by(servergroup_id=gid,
                                                shared=True).all()
        if shared_servers:
            return make_json_response(
                status=417,
                success=0,
                errormsg=gettext(
