        """Open the given URL in a new browser window.
        Display an error dialog if everything fails.
        """
        (r, w) = os.pipe()
        if os.fork() > 0:
            os.close(w)
            status = os.wait()[1]
            if status:
                title = _("Unable to start web browser")
                error = _("Unable to start web browser to open %s." % url)
                message = os.fdopen(r).readline()
                if message:
                    error += "\n" + message
