def _checknetloc(netloc):
    if not netloc or not isinstance(netloc, unicode):
        return
    import unicodedata
    n = netloc.rpartition('@')[2]
    n = n.replace(':', '')
    n = n.replace('#', '')
    n = n.replace('?', '')
    netloc2 = unicodedata.normalize('NFKC', n)
    if n == netloc2:
        return
