            click.echo("Found 0 installed package, skip purging.")
            click.echo(crayons.green("Environment now purged and fresh!"))
        return installed
    if not bare:
        click.echo(
            fix_utf8(f"Found {len(to_remove)} installed package(s), purging...")
        )
    command = [
