def fix_bad_arg_names(func, arg):
    if arg.name == 'str':
        return 'str_'
    if arg.name == 'len':
        return 'length'
    if arg.name == 'repr':
        return 'repr_'
    if func.name == 'open' and arg.name == 'vararg':
