def prevent_open_redirect(url):
    host = current.request.env.http_host
    print(host)
    if not url:
        return None
    if REGEX_OPEN_REDIRECT.match(url):
        parts = url.split('/')
        if len(parts) > 2 and parts[2] == host:
            return url
        return None
    return url

