    XBlockWithSettingsMixin,
    ThemableXBlockMixin
):
    @property
    def zones(self):
        """
        Get drop zone data, defined by the author.
        """
        migrator = StateMigration(self)
        migrated_zones = []
        for zone in self.data.get('zones', []):
