            index = data["startAt"] + data["maxResults"]
            while data["total"] > index:
                query["startAt"] = index
                response, error = self.get_response(jql_url, params=query)
                if error is not None:
                    return None, error
                data = response.json()
                index = data["startAt"] + data["maxResults"]
