class Task:
    @classmethod
    def new_task(cls, user: User, sample: BytesIO, filename: str, disabled_workers: List[str],
                 parent: Optional['Task']=None, password: Optional[str]=None) -> 'Task':
        task_uuid = str(uuid4())
