        )
        disk_info
        size, avail, total_inodes, fstype = disk_info.strip().split()
        total_inodes = int(total_inodes[:-1])
        inode_size = {
            "ext4": 256,
            "small": 128,
            "floppy": 128,
            "hurd": 128,
        }.get(fstype, 256)
        total_inodes_size = total_inodes * inode_size * 1e-9
